import * as cdk from 'aws-cdk-lib';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';
import * as apigw from 'aws-cdk-lib/aws-apigatewayv2';
import { HttpLambdaIntegration } from 'aws-cdk-lib/aws-apigatewayv2-integrations';
import { Construct } from 'constructs';

export class OrdersStack extends cdk.Stack {
  constructor(scope: Construct, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    const table = new dynamodb.Table(this, 'Orders', {
      partitionKey: { name: 'orderId', type: dynamodb.AttributeType.STRING },
      billingMode: dynamodb.BillingMode.PAY_PER_REQUEST,
      pointInTimeRecoverySpecification: { pointInTimeRecoveryEnabled: true },
      removalPolicy: cdk.RemovalPolicy.RETAIN,
    });

    const fn = new lambda.Function(this, 'GetOrder', {
      runtime: lambda.Runtime.PYTHON_3_12,
      architecture: lambda.Architecture.ARM_64,
      handler: 'app.handler',
      code: lambda.Code.fromAsset('src/get_order'),
      timeout: cdk.Duration.seconds(25),
      environment: { TABLE_NAME: table.tableName },
    });

    table.grantReadData(fn);

    const api = new apigw.HttpApi(this, 'OrdersApi');
    api.addRoutes({
      path: '/orders/{id}',
      methods: [apigw.HttpMethod.GET],
      integration: new HttpLambdaIntegration('GetOrderIntegration', fn),
    });

    new cdk.CfnOutput(this, 'ApiUrl', { value: api.apiEndpoint });
  }
}

const cfnTable = table.node.defaultChild as dynamodb.CfnTable;
cfnTable.addPropertyOverride('SSESpecification.SSEType', 'KMS');
cfnTable.addOverride('Properties.TableClass', 'STANDARD_INFREQUENT_ACCESS');

import { Template, Match } from 'aws-cdk-lib/assertions';

test('table has PITR and is retained', () => {
  const app = new cdk.App();
  const stack = new OrdersStack(app, 'Test');
  const template = Template.fromStack(stack);

  template.hasResourceProperties('AWS::DynamoDB::Table', {
    PointInTimeRecoverySpecification: { PointInTimeRecoveryEnabled: true },
  });
  template.hasResource('AWS::DynamoDB::Table', {
    DeletionPolicy: 'Retain',
  });
});

test('lambda cannot write to the table', () => {
  const template = Template.fromStack(new OrdersStack(new cdk.App(), 'Test'));
  template.resourceCountIs('AWS::DynamoDB::Table', 1);
  const policies = template.findResources('AWS::IAM::Policy');
  expect(JSON.stringify(policies)).not.toContain('dynamodb:PutItem');
});

class RequireEncryption implements cdk.IAspect {
  visit(node: Construct): void {
    if (node instanceof s3.CfnBucket && !node.bucketEncryption) {
      cdk.Annotations.of(node).addError('S3 buckets must be encrypted');
    }
  }
}

cdk.Aspects.of(app).add(new RequireEncryption());
